package com.jay.fxi.data.entitlements

import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.CoroutineStart
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.launch
import kotlinx.coroutines.test.TestScope
import kotlinx.coroutines.test.UnconfinedTestDispatcher
import kotlinx.coroutines.test.runTest
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/**
 * CAP-K08·CAP-K24 (R10, s6_2b0b_contracts.r4.md 4.3·5절, Codex 시험 검토 r1 ⑧·r2 질문 2).
 *
 * HEAD API만 쓴다. 단계별 상태 줄에 더해, 입력 전에 시작한 수집기로 공개 `krx`·`state` 흐름의 값 열(state는 소유자·세대 포함 전체),
 * 발행(accessRevisions)을 관측한 시점 snapshot의 기존 필드 전체, 조회 기록 전체를 남긴다. 수집기는 즉시 재개되는 dispatcher라 한 단계 안의 중간 변화도 남는다(양성 대조 D4).
 * accessRevisions는 StateFlow라 같은 스레드에서 연달아 오른 값은 합쳐질 수 있다. 그래서 발행 이력은 '관측된 발행'이고, 단계 줄의
 * rev와 함께 읽는다.
 *
 * 기대 기록은 운영 소스가 e0eef8e 그대로인 트리에서 이 시험의 TRACE 출력으로 뽑았다. candidate(스위치 기본 꺼짐)도 같은 기록을
 * 내야 한다. 다르면 실제 줄을 TRACE 접두로 출력하고 실패한다.
 */
@OptIn(ExperimentalCoroutinesApi::class)
class PremiumAccessKrxDormantTraceTest {

    private val processJob = SupervisorJob()

    private class History {
        val krx = mutableListOf<String>()
        val state = mutableListOf<String>()
        val published = mutableListOf<String>()
    }

    /** 입력 전에 부른다. 수집기는 backgroundScope에서 돌아 시험 끝에 함께 취소된다. */
    private fun TestScope.collectHistory(h: KrxHarness): History {
        val history = History()
        val eager = UnconfinedTestDispatcher(testScheduler)
        backgroundScope.launch(eager) { h.coordinator.krx.collect { history.krx += it.toString() } }
        backgroundScope.launch(eager) { h.coordinator.state.collect { history.state += it.toString() } }
        backgroundScope.launch(eager) {
            h.coordinator.accessRevisions.collect { revision ->
                val s = h.coordinator.accessSnapshot
                history.published +=
                    "$revision:${s.revision}:${s.facts}:${s.userInvalidations}:" +
                    "${s.lastUserEnd}:${s.lastCapabilityEnd}:${s.userEndInvalidationsFloor}"
            }
        }
        return history
    }

    private fun historyLines(h: KrxHarness, history: History): List<String> = listOf(
        "krxHistory=${history.krx.joinToString(",")}",
        "stateHistory=${history.state.joinToString(",")}",
        "published=${history.published.joinToString(",")}",
        "calls=${h.source.calls.joinToString(",") { "${it.index}@${it.atMillis}:${it.freshPremium}" }}"
    )

    private fun traceTest(name: String, golden: List<String>, body: suspend TestScope.(MutableList<String>) -> Unit) = runTest {
        val lines = mutableListOf<String>()
        try {
            body(lines)
        } catch (failed: Throwable) {
            lines.forEachIndexed { i, line -> println("TRACE[$name][$i] $line") }
            throw failed
        } finally {
            processJob.cancel()
        }
        if (lines != golden) {
            lines.forEachIndexed { i, line -> println("TRACE[$name][$i] $line") }
            fail("$name: 기록이 HEAD 기준과 다르다(실제 ${lines.size}줄, 기준 ${golden.size}줄). TRACE 줄을 보라")
        }
    }

    private val active = EntitlementsOutcome.StableActive(krxVisible = true)
    private val krxFalse = EntitlementsOutcome.StableActive(krxVisible = false)

    /** D1: (거절 → FE true) × 3, 이어 (거절 → FE false) 뒤 CALLER FP의 true. */
    @Test
    fun d1_rejectionsAndAnswersAlternating() = traceTest("D1", GOLDEN_D1) { out ->
        val h = krxHarness(processJob)
        val history = collectHistory(h)
        h.grantedKrxVisible()
        out += h.traceLine("granted")
        repeat(3) { i ->
            h.source.next = { active }
            h.rejectKrx(h.issueGrant())
            out += h.traceLine("reject#$i")
            step(100)
            out += h.traceLine("fe#$i")
            settleKrx()
            out += h.traceLine("settled#$i")
        }
        h.source.next = { krxFalse }
        h.rejectKrx(h.issueGrant())
        step(100)
        out += h.traceLine("reject-false")
        settleKrx()
        out += h.traceLine("settled-false")
        h.source.next = { active }
        h.coordinator.refresh(RefreshIntent.FORCE_PREMIUM)
        step(100)
        out += h.traceLine("caller-fp")
        settleKrx()
        out += h.traceLine("settled-fp")
        out += historyLines(h, history)
    }

    /** D2: 미결정 거절 두 분기(live 판독 실패, store.load 실패 후보 보류). */
    @Test
    fun d2_undecidedRejections() = traceTest("D2", GOLDEN_D2) { out ->
        val h = krxHarness(processJob)
        val history = collectHistory(h)
        h.grantedKrxVisible()
        val liveGrant = h.issueGrant()   // 발급도 신원을 읽으므로 실패 주입은 발급 뒤에 둔다
        h.source.identityNulls = 1
        h.rejectKrx(liveGrant)
        out += h.traceLine("live-null")
        step(5_000)
        out += h.traceLine("live-floor")
        settleKrx()
        out += h.traceLine("live-settled")
        val loadGrant = h.issueGrant()
        h.store.loadFailures = 1
        h.rejectKrx(loadGrant)
        out += h.traceLine("load-fail")
        settleKrx()
        out += h.traceLine("load-settled")
        out += historyLines(h, history)
    }

    /** D3 = CAP-K24(보충 A1 K16): 회전 실패 → seal 중 FE true 억제 → 해제·재승인. */
    @Test
    fun d3_rotationFailureSealAndRelease() = traceTest("D3", GOLDEN_D3) { out ->
        val h = krxHarness(processJob)
        val history = collectHistory(h)
        h.grantedKrxVisible()
        h.store.rotationFailures = 2   // H1 회전과 첫 복구 라운드가 실패해, 해제 전에 FE 답이 seal 중에 적용된다
        h.source.next = { active }
        h.rejectKrx(h.issueGrant())
        out += h.traceLine("reject-sealed")
        step(0)
        out += h.traceLine("fe-applied")
        step(KrxHarnessDefaults.RETRY)
        out += h.traceLine("after-retry")
        settleKrx()
        out += h.traceLine("settled")
        out += historyLines(h, history)
    }

    /**
     * D4 양성 대조: 거절 뒤 단계 표본 없이 FE true까지 진행하면 단계 줄은 VISIBLE만 본다. 이력 수집기는 그 사이의 HIDDEN을 남겨야
     * 한다. 이 단언이 깨지면 이력 기록이 중간 변화를 못 잡는 것이므로 다른 기록의 일치도 근거가 약해진다.
     */
    @Test
    fun d4_intraStepChangeIsCaptured() = traceTest("D4", GOLDEN_D4) { out ->
        val h = krxHarness(processJob)
        val history = collectHistory(h)
        h.grantedKrxVisible()
        out += h.traceLine("granted")
        h.source.next = { active }
        h.rejectKrx(h.issueGrant())
        step(100)
        out += h.traceLine("after-step")
        assertTrue(
            "같은 단계 안의 HIDDEN이 이력에 남는다: ${history.krx}",
            history.krx.windowed(3).any { it == listOf("VISIBLE", "HIDDEN", "VISIBLE") }
        )
        out += historyLines(h, history)
    }

    /**
     * D5 질의 후보의 결정과 Stale 해제(r8, 사전 변이 C_guard_024·027 판별): H1′(FE 요구, 5초 floor) 전에 시작한 CALLER FE의 false가 답 적용
     * load 실패로 질의 후보 → 첫 복구 라운드에서 결정(그 답은 요구보다 먼저 시작해 정산하지 않는다) → CALLER FP의 Pending(false, 30초)이
     * (H1′ FE가 정산한 뒤) 질의 후보(첫 라운드 신원 미확인으로 유지, 진술 floor 기록) → capability epoch만 이동해 Stale 해제 → 정착.
     */
    @Test
    fun d5_queryCandidateDecisionAndStaleRelease() = traceTest("D5", GOLDEN_D5) { out ->
        val h = krxHarness(processJob)
        val history = collectHistory(h)
        h.grantedKrxVisible()
        val q1Gate = CompletableDeferred<EntitlementsOutcome>()
        h.source.gates.addLast(q1Gate)
        val q1 = launch(start = CoroutineStart.UNDISPATCHED) { h.coordinator.refresh(RefreshIntent.FORCE_ENTITLEMENTS) }
        h.undecidedRejection()
        out += h.traceLine("q1-then-undecided")
        h.store.loadFailures = 1
        q1Gate.complete(krxFalse)
        step(0)
        out += h.traceLine("q1-candidate-decided")
        settleKrx()   // H1′의 FE(5초 floor)가 돌아 요구를 정산하고 floor가 걷힌다
        out += h.traceLine("undecided-settled")
        h.source.next = { EntitlementsOutcome.Pending(krxVisible = false, retryAfterSeconds = 30) }
        h.store.loadSkipsBeforeFailure = 1   // FP 시작 load는 통과, 답 적용 load만 실패 → 질의 후보(진술 floor 30초)
        h.store.loadFailures = 1
        h.source.identityNulls = 1           // 첫 복구 라운드는 신원 미확인으로 후보 유지
        h.coordinator.refresh(RefreshIntent.FORCE_PREMIUM)
        step(0)
        out += h.traceLine("fp-pending-candidate-held")
        h.store.beginRotation(rotateUser = false, rotateKrx = true)
        h.source.next = { active }
        step(KrxHarnessDefaults.RETRY)
        out += h.traceLine("stale-released")
        settleKrx()
        out += h.traceLine("settled")
        q1.join()
        out += historyLines(h, history)
    }

    /**
     * D6 후보 해제 중 지연 0 재조회의 발화(r8, 사전 변이 C_guard_025 반증 보완): KRX 단독 질의 후보(KrxEntitlementRequired, 답 적용 load 실패)를
     * 복구 결정하면 정산이 지연 0 FE 재조회를 무장한다. 후보 해제의 발행 순간에 RS 타이머가 다른 작업자에서 발화하는 순서(운영 scope는
     * Dispatchers.Default)를, 발행 수집기 안의 runCurrent로 재현한다. HEAD는 해제 뒤 schedule을 건드리지 않아 그 FE가 같은 시각에 나간다.
     * 해제 뒤 무장을 더하는 변이는 발화된 타이머를 취소하고 5초 백오프로 미룬다.
     */
    @Test
    fun d6_zeroDelayRecheckFiresDuringCandidateRelease() = traceTest("D6", GOLDEN_D6) { out ->
        val h = krxHarness(processJob)
        val history = collectHistory(h)
        h.grantedKrxVisible()
        out += h.traceLine("granted")
        var drainAtRelease = false
        backgroundScope.launch(UnconfinedTestDispatcher(testScheduler)) {
            h.coordinator.accessRevisions.collect {
                if (drainAtRelease && TopicAccessBlock.LOSS_CANDIDATE !in h.coordinator.accessSnapshot.facts.capabilityBlocks) {
                    drainAtRelease = false
                    testScheduler.runCurrent()
                }
            }
        }
        h.source.next = { EntitlementsOutcome.KrxEntitlementRequired }
        h.store.loadSkipsBeforeFailure = 1
        h.store.loadFailures = 1
        h.coordinator.refresh(RefreshIntent.FORCE_ENTITLEMENTS)
        out += h.traceLine("held")
        h.source.next = { active }
        drainAtRelease = true
        step(0)
        out += h.traceLine("resolved")
        settleKrx()
        out += h.traceLine("settled")
        out += historyLines(h, history)
    }

    /** CAP-K24(보충 A1 K17): seal 중 FE true 억제 뒤 해제 전에 늦게 시작한 CALLER의 false. */
    @Test
    fun k17_laterFalseAfterSuppressedTrue() = traceTest("K17", GOLDEN_K17) { out ->
        val h = krxHarness(processJob)
        val history = collectHistory(h)
        h.grantedKrxVisible()
        h.store.rotationFailures = 2
        h.source.next = { active }
        h.rejectKrx(h.issueGrant())
        step(0)
        out += h.traceLine("suppressed")
        h.source.next = { krxFalse }
        h.coordinator.refresh(RefreshIntent.FORCE_PREMIUM)
        step(100)
        out += h.traceLine("caller-false")
        settleKrx()
        out += h.traceLine("settled")
        out += historyLines(h, history)
    }

    /**
     * CAP-K24(보충 A1 K18) 완료 순서 역전. ON 시험과 같은 입력: H1(회전 실패·seal) → CALLER FE q1을 UNDISPATCHED로 즉시 시작
     * (gate, 답 false) → scheduler 실행(예약 FE는 진행 중 q1이 덮어 시작하지 않는다, PAC:1551-1556) → CALLER FP q2의 true가
     * seal 중 억제 → q1 false 적용.
     */
    @Test
    fun k18_completionInversion() = traceTest("K18", GOLDEN_K18) { out ->
        val h = krxHarness(processJob)
        val history = collectHistory(h)
        h.grantedKrxVisible()
        h.store.rotationFailures = 2
        h.source.next = { active }
        h.rejectKrx(h.issueGrant())
        out += h.traceLine("rejected-sealed")
        val q1Gate = CompletableDeferred<EntitlementsOutcome>()
        h.source.gates.addLast(q1Gate)
        val q1 = launch(start = CoroutineStart.UNDISPATCHED) { h.coordinator.refresh(RefreshIntent.FORCE_ENTITLEMENTS) }
        out += h.traceLine("q1-started")
        step(0)
        out += h.traceLine("scheduler-ran")
        val q2 = launch { h.coordinator.refresh(RefreshIntent.FORCE_PREMIUM) }
        step(100)
        out += h.traceLine("q2-suppressed")
        q1Gate.complete(krxFalse)
        step(0)
        out += h.traceLine("q1-false-applied")
        q1.join()
        q2.join()
        settleKrx()
        out += h.traceLine("settled")
        out += historyLines(h, history)
    }

    private companion object {
        // 기준 기록: 운영 소스가 e0eef8e 그대로인 트리에서 이 시험의 TRACE 출력으로 뽑았다(5절, 증거 s6_2b0b/head_trace_r4/).
        val GOLDEN_D1: List<String> = listOf(
            "granted | krx=VISIBLE | state=PremiumConfirmed | rev=6 | facts=TopicAccessFacts(token=null, issuedFor=null, binding=EntitlementsIdentity(ownerUid=user-a, authGeneration=1), recordFence=AccessFence(ownerUid=user-a, userAccessEpoch=epoch-0, krxCapabilityEpoch=epoch-1), decisionGeneration=1, tokenStanding=false, userBlocks=[], capabilityBlocks=[], recordUnconfirmed=false, userContextUncertain=false, capabilityContextUncertain=false) | inv=0 | uEnd=null | cEnd=null | floor=0 | fetches=1 | last=0:true | loads=4 | rot=0 | rec=AccessEpochRecord(ownerUid=user-a, userAccessEpoch=epoch-0, krxCapabilityEpoch=epoch-1, mayContainPremiumData=true, mayContainKrxData=true, pendingPurges=[], teardownOwedFor=null) | purge=0 | reapp=[] | armed=false | attempts=0 | floorAt=null | intent=null | rsRev=2",
